<?php
declare(strict_types=1);
namespace Liberu\ControlPanel\Monitoring\Actions;
use Illuminate\Support\Str; use Illuminate\Validation\ValidationException; use Illuminate\Database\Eloquent\Model;
final class RecordMonitoringResource { public function execute(array $a):Model { $kind=(string)($a['kind']??''); $map=['metric'=>\Liberu\ControlPanel\Monitoring\Models\MetricSample::class,'log'=>\Liberu\ControlPanel\Monitoring\Models\LogEntry::class,'uptime'=>\Liberu\ControlPanel\Monitoring\Models\UptimeCheck::class,'capacity'=>\Liberu\ControlPanel\Monitoring\Models\CapacitySnapshot::class,'alert'=>\Liberu\ControlPanel\Monitoring\Models\AlertRule::class,'incident'=>\Liberu\ControlPanel\Monitoring\Models\Incident::class,'maintenance'=>\Liberu\ControlPanel\Monitoring\Models\MaintenanceWindow::class,'status'=>\Liberu\ControlPanel\Monitoring\Models\StatusSnapshot::class]; if(!isset($map[$kind]))throw ValidationException::withMessages(['kind'=>'Unsupported monitoring resource.']); $attributes=$a; unset($attributes['kind']); $attributes['id']=$attributes['id']??(string)Str::uuid(); $attributes['team_id']=$a['team_id']??null; if($kind==='maintenance')$attributes['status']=$attributes['status']??'scheduled'; if($kind==='incident')$attributes['status']=$attributes['status']??'open'; return $map[$kind]::query()->create($attributes); } }
